+        const char* tr = std::getenv("STRATA_P4_TRACE");
+        if (tr != nullptr) {
+            const char* path = (tr[0] == '\0' || std::strcmp(tr, "1") == 0) ? "strata-p4-trace.csv" : tr;
+            trace_ = std::fopen(path, "w");
